<script setup lang="ts">
import { ref,onMounted } from 'vue';
import axios from 'axios';
const items=ref<{id:number;title:string;status:string;price:number;description:string;location:string;imageUrl:string}[]>([]),error=ref(''),busy=ref(false);
const publishDialog=ref<HTMLDialogElement|null>(null);
function openPublish(){editing.value=null;title.value='';description.value='';price.value='';location.value='';selectedPhoto.value=null;error.value='';publishDialog.value?.showModal();}
function closePublish(){if(!busy.value)publishDialog.value?.close();}
const editing=ref<number|null>(null), selectedPhoto=ref<File|null>(null);
const title=ref(''),description=ref(''),price=ref(''),location=ref('');
async function load(){try{items.value=(await axios.get('/api/my/products')).data;}catch{error.value='请先点击右上角登录，再刷新此页。';}}
async function headers(){return {'X-XSRF-TOKEN':(await axios.get('/api/auth/csrf')).data.token};}
async function edit(id:number){const p=items.value.find(x=>x.id===id);if(!p)return;editing.value=id;title.value=p.title;description.value=p.description;price.value=String(p.price);location.value=p.location;error.value='';publishDialog.value?.showModal();}
async function upload(id:number,event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;error.value='';const data=new FormData();data.append('file',file);try{await axios.post('/api/my/products/'+id+'/image',data,{headers:await headers()});await load();}catch{error.value='上传失败：请选择5MB以内的JPEG或PNG图片，并确认商品仍在售。';}}
async function publish(){busy.value=true;error.value='';try{if(!editing.value){if(!selectedPhoto.value){error.value='请选择商品图片';return;}const data=new FormData();data.append('product',new Blob([JSON.stringify({title:title.value,description:description.value,price:price.value,location:location.value})],{type:'application/json'}));data.append('file',selectedPhoto.value);await axios.post('/api/my/products/publish',data,{headers:await headers()});selectedPhoto.value=null;}else await axios.request({method:editing.value?'PUT':'POST',url:'/api/my/products'+(editing.value?'/'+editing.value:''),data:{title:title.value,description:description.value,price:price.value,location:location.value},headers:await headers()});editing.value=null;title.value='';description.value='';price.value='';location.value='';publishDialog.value?.close();await load();}catch{error.value='发布失败，请检查输入及登录状态。';}finally{busy.value=false;}}
async function withdraw(id:number){if(!confirm('确认下架这件商品？'))return;try{await axios.post('/api/my/products/'+id+'/withdraw',null,{headers:await headers()});await load();}catch{error.value='下架失败，请刷新后重试。';}}
onMounted(load);
</script>
<template><section class="my-products"><div class="profile-heading"><div><p class="profile-eyebrow">SHANDONG UNIVERSITY / MY CAMPUS</p><h1>个人主页</h1><p>让闲置好物，在山大遇见新主人。</p></div><button type="button" class="publish-entry" @click="openPublish"><span class="sdu-stamp">山大</span><span class="fish-symbol" aria-hidden="true">><span>●</span>))°</span><span class="entry-copy"><strong>发布闲置</strong><small>校园好物 · 闲不住的生活</small></span><span class="entry-plus">＋</span></button></div><p role="alert">{{ error }}</p><dialog ref="publishDialog" class="publish-dialog" aria-labelledby="publish-title" @cancel="busy && $event.preventDefault()" @click="($event.target===publishDialog) && closePublish()"><button class="dialog-close" type="button" aria-label="关闭发布窗口" :disabled="busy" @click="closePublish">×</button><p class="dialog-eyebrow">山大好物 / CAMPUS REUSE</p><form @submit.prevent="publish"><h2 id="publish-title">{{ editing?'编辑商品':'发布校园好物' }}</h2><label>商品名称<input v-model="title" required maxlength="120"></label><label>商品描述<textarea v-model="description" required maxlength="5000"></textarea></label><label>价格（元）<input v-model="price" required type="number" min="0.01" max="99999999.99" step="0.01"></label><label>交易地点<input v-model="location" required maxlength="120"></label><label v-if="!editing">商品图片<input type="file" accept="image/jpeg,image/png" required @change="selectedPhoto=($event.target as HTMLInputElement).files?.[0] || null"></label><p role="alert" class="form-error">{{ error }}</p><small>首次发布时请选择商品图片，支持5MB以内JPEG或PNG。</small><button :disabled="busy">{{ busy?'保存中…':editing?'保存修改':'发布商品' }}</button><button v-if="editing" type="button" @click="closePublish">取消编辑</button></form></dialog><h2>我的商品</h2><p v-if="!items.length">暂无发布记录。</p><article v-for="item in items" :key="item.id"><img class="thumbnail" :src="item.imageUrl" :alt="item.title"><RouterLink :to="'/market/'+item.id">{{ item.title }}</RouterLink><span>¥ {{ item.price }} · {{ item.status==='AVAILABLE'?'在售':'已下架' }}</span><button v-if="item.status==='AVAILABLE'" @click="edit(item.id)">编辑</button><label v-if="item.status==='AVAILABLE'" class="upload">上传图片<input type="file" accept="image/jpeg,image/png" @change="upload(item.id,$event)"></label><button v-if="item.status==='AVAILABLE'" @click="withdraw(item.id)">下架</button></article></section></template>
<style scoped>.my-products{background:#f6f4ee;color:#293d3b;padding:40px max(6%,20px);flex:1}.my-products h1{font-size:32px;margin:0 0 15px}form{max-width:620px;background:white;padding:28px;border-radius:8px;margin:25px 0}label{display:block;font-size:14px;margin:18px 0}input,textarea{display:block;width:100%;padding:12px;margin-top:8px;border:1px solid #ccd3c9;font:inherit;border-radius:4px}textarea{min-height:100px}small{display:block;color:#8b7959;margin-bottom:18px}button{padding:12px 22px;border:0;border-radius:4px;background:#304b49;color:white}button:disabled{opacity:.5}article{display:flex;gap:25px;align-items:center;background:white;padding:20px;margin:12px 0;flex-wrap:wrap}a{color:#304b49}article span{font-size:13px}.thumbnail{width:70px;height:70px;object-fit:contain}.upload{font-size:12px}.upload input{max-width:210px;font-size:11px}.profile-heading{display:flex;justify-content:space-between;align-items:center;gap:25px;margin:5px 0 45px}.profile-eyebrow{font-size:10px;letter-spacing:2px;color:#92724b}.publish-entry{display:flex;align-items:center;gap:16px;background:#ffe56b;color:#342c23;border:1px solid #f3d550;border-radius:18px;padding:21px 25px;box-shadow:0 8px 0 #ddc15b30;transition:transform .2s}.publish-entry:hover{transform:translateY(-3px)}.sdu-stamp{display:grid;place-items:center;width:44px;height:44px;border:2px solid #983f40;color:#983f40;font-family:serif;font-size:18px;border-radius:50%;transform:rotate(-9deg)}.fish-symbol{font-size:24px;font-weight:bold;letter-spacing:-4px}.fish-symbol span{font-size:15px}.entry-copy{text-align:left}.entry-copy strong{font-size:20px;letter-spacing:2px}.entry-copy small{color:#665b38;font-size:10px;margin:6px 0 0}.entry-plus{font-size:28px;margin-left:15px}.publish-dialog{position:fixed;width:min(610px,calc(100% - 32px));max-height:88svh;padding:30px;border:1px solid #ffffff80;border-radius:18px;background:#fffaf2;color:#293d3b;box-shadow:0 30px 90px #0004;overflow:auto}.publish-dialog::backdrop{background:#142a35a6;backdrop-filter:blur(7px)}.publish-dialog form{padding:0;background:none;margin:12px 0 0;max-width:none}.publish-dialog h2{font-size:25px;margin:12px 0 25px}.dialog-eyebrow{font-size:10px;color:#967449;letter-spacing:2px;margin:0}.dialog-close{position:absolute;right:16px;top:12px;background:transparent;color:#52665d;font-size:26px;padding:4px 10px}.form-error{color:#a34536;font-size:13px}.publish-dialog form>button{margin-right:12px}@media(max-width:700px){.profile-heading{align-items:stretch;flex-direction:column}.publish-entry{justify-content:center}.publish-dialog{padding:24px}.publish-entry .entry-plus{margin-left:auto}}@media(prefers-reduced-motion:reduce){.publish-entry{transition:none}}
</style>
